mapper.select:
select  
from    t_entry_common
where 1=1 and  is_latest_version = 1

    and
    abbr  like CONCAT('%','${entryEntity.abbr}','%' )


    and   chinese   like CONCAT('%','${entryEntity.chinese}','%' )


    and chinese_length = #{entryEntity.chineseLength,jdbcType=INTEGER}


    and   chinese_interpretation = #{entryEntity.chineseInterpretation,jdbcType=VARCHAR}


    and englishinterpretation = #{entryEntity.englishInterpretation,jdbcType=VARCHAR}


    and entry_source = #{entryEntity.entrySource,jdbcType=VARCHAR}


    and  entry_state in (${entryState})


    and  creator like CONCAT('%','${entryEntity.creator}','%' )


    and  create_time >=    #{entryEntity.createTime,jdbcType=DATETIMEOFFSET}


    and create_time <=    #{entryEntity.createEndRTime,jdbcType=DATETIMEOFFSET}


    and version = #{entryEntity.version,jdbcType=VARCHAR}


    and is_latest_version = #{entryEntity.isLatestVersion,jdbcType=INTEGER}


    and entry_label = #{entryEntity.entryLabel,jdbcType=VARCHAR}


    and part_of_speech like CONCAT('%','${entryEntity.partOfSpeech}','%' )


    and classify_id in (

        #{classify.key,jdbcType=VARCHAR}

    )


    and repeatEntryId = #{entryEntity.repeatEntryId,jdbcType=VARCHAR}


    and english =#{entryEntity.english,jdbcType=VARCHAR}


    and english_length = #{entryEntity.englishLength,jdbcType=INTEGER}


    and english_translate_state = #{entryEntity.englishTranslateState,jdbcType=VARCHAR}


    and  english_disable = #{entryEntity.englishDisable,jdbcType=VARCHAR}


    and english_disable_length = #{entryEntity.englishDisableLength,jdbcType=INTEGER}


    and russian = #{entryEntity.russian,jdbcType=VARCHAR}


    and russian_length = #{entryEntity.russianLength,jdbcType=INTEGER}


    and russian_translate_state = #{entryEntity.russianTranslateState,jdbcType=VARCHAR}


    and  spanish = #{entryEntity.spanish,jdbcType=VARCHAR}


    and spanish_length = #{entryEntity.spanishLength,jdbcType=INTEGER}


    and  spanish_translate_state = #{entryEntity.spanishTranslateState,jdbcType=VARCHAR}


    and french = #{entryEntity.french,jdbcType=VARCHAR}


    and french_length = #{entryEntity.frenchLength,jdbcType=INTEGER}


    and french_translate_state = #{entryEntity.frenchTranslateState,jdbcType=VARCHAR}


    remark = #{entryEntity.remark,jdbcType=VARCHAR}



    type_id = #{entryEntity.typeId,jdbcType=VARCHAR}


    environment_remark = #{entryEntity.environmentRemark,jdbcType=VARCHAR}




order by update_time desc

    LIMIT #{limit} OFFSET #{offset}

